import{c as r,Q as d,j as a,m as e}from"./chunks/framework.rWdQudnF.js";const c=JSON.parse('{"title":"架构师-备考 论文写作-写作要求和框架","description":"","frontmatter":{"title":"架构师-备考 论文写作-写作要求和框架"},"headers":[],"relativePath":"论文写作/写作要求和框架.md","filePath":"论文写作/写作要求和框架.md","lastUpdated":null}'),l={name:"论文写作/写作要求和框架.md"};function o(i,t,n,h,s,b){return d(),a("div",null,[...t[0]||(t[0]=[e('<h2 id="考点清单" tabindex="-1">考点清单 <a class="header-anchor" href="#考点清单" aria-label="Permalink to &quot;考点清单&quot;">​</a></h2><ul><li>[x] 论文考试范围（四选一，5 大主题）</li><li>[x] 论文要求（形式 + 内容，11 条规则）</li><li>[x] 评分标准（扣分项 + 加分项 + 不及格项）</li><li>[x] 论文框架（摘要→背景→过渡→理论→实践→结尾，含字数建议）</li><li>[x] 项目选择策略（5W2H 模式）</li><li>[x] 备考建议</li></ul><h2 id="笔记" tabindex="-1">笔记 <a class="header-anchor" href="#笔记" aria-label="Permalink to &quot;笔记&quot;">​</a></h2><h3 id="一、考试概况" tabindex="-1">一、考试概况 <a class="header-anchor" href="#一、考试概况" aria-label="Permalink to &quot;一、考试概况&quot;">​</a></h3><blockquote><p>系统架构设计师考试论文题目一般是<strong>四选一</strong>，范围覆盖系统建模、软件架构设计、系统设计、系统可靠性分析与设计、系统安全性和保密性设计等方面。</p></blockquote><p><strong>学习前提：</strong></p><ol><li>课程内容学习完毕</li><li>课程练习题练习完毕</li><li>论文学习 + 案例并行学习</li><li>确认论文模版，根据模版练习 6 篇左右的论文（一周一篇，考试前一个月）</li></ol><p><strong>考试大纲范围：</strong> 系统建模 / 软件架构设计 / 系统分析与设计 / 系统可靠性分析与设计 / 系统安全性和保密性设计 / 项目管理</p><hr><h3 id="二、论文要求-★" tabindex="-1">二、论文要求 ★ <a class="header-anchor" href="#二、论文要求-★" aria-label="Permalink to &quot;二、论文要求 ★&quot;">​</a></h3><p><strong>11 条核心规则：</strong></p><table tabindex="0"><thead><tr><th>#</th><th>规则</th></tr></thead><tbody><tr><td>1</td><td>不要猜题，要复用构件（摘要+项目背景+结尾），不要整篇复用</td></tr><tr><td>2</td><td>不要抄范文，选择适合自己的范文进行修改，改成自己的论文</td></tr><tr><td>3</td><td>提前准备好要写的项目，必须是<strong>近三年内</strong>的中大型商业项目</td></tr><tr><td>4</td><td>做好准备工作，练习论文时发现有不会的知识点，一定要全部背会</td></tr><tr><td>5</td><td>要勇于迈出第一步，第一篇论文不限时间</td></tr><tr><td>6</td><td>写正文时，不要生硬地回答问题，要根据问题要点组合成一篇通顺的文章</td></tr><tr><td>7</td><td>字数一般在 <strong>300 + 2200</strong> 左右，写到最后一页上面，字迹一定要完整、一笔一划</td></tr><tr><td>8</td><td>从系统架构设计师的角度看项目，技术细节要少且精，书本理论要与实际项目联系</td></tr><tr><td>9</td><td>可以局部段落列举 123，论点分开论述，没必要都写编号</td></tr><tr><td>10</td><td>论述要求：不能口语化、文档段落不宜太长</td></tr><tr><td>11</td><td>换个角度看论文，以论文写作技巧视频为依据，对自己的论文进行自评</td></tr></tbody></table><p><strong>形式要求 vs 内容要求：</strong></p><table tabindex="0"><thead><tr><th>维度</th><th>要求</th></tr></thead><tbody><tr><td><strong>形式</strong>（表/数量）</td><td>字数要够（摘要 290~320 字，正文 2200~2800 字）；卷面整洁、字迹易辨认；无明显语法文法纰漏，行文清晰有逻辑</td></tr><tr><td><strong>内容</strong>（里/质量）</td><td>实践性强、切忌夸大其词；契合题意不跑题；具备较高深度和水平；体现较强的综合分析能力；体现较好的书面表达能力</td></tr></tbody></table><hr><h3 id="三、评分标准-★" tabindex="-1">三、评分标准 ★ <a class="header-anchor" href="#三、评分标准-★" aria-label="Permalink to &quot;三、评分标准 ★&quot;">​</a></h3><p><strong>扣分项（扣 5~10 分）：</strong></p><table tabindex="0"><thead><tr><th>情况</th></tr></thead><tbody><tr><td>没有写论文摘要、摘要过于简略、或摘要中没有实质性内容</td></tr><tr><td>字迹比较潦草、其中有不少字难以辨认</td></tr><tr><td>确实属于过分自我吹嘘或自我标榜、夸大其词</td></tr><tr><td>内容有明显错误漏洞的，按同一类错误每一类扣一次分</td></tr><tr><td>内容仅属于大学生或研究生实习性质的项目、且实际应用水平相对较低</td></tr></tbody></table><p><strong>加分项（加 5~10 分）：</strong></p><table tabindex="0"><thead><tr><th>情况</th></tr></thead><tbody><tr><td>有独特的见解或有着很深入的体会、相对非常突出</td></tr><tr><td>起点很高，确实符合当今信息系统发展的新趋势与新动向，并能加以应用</td></tr><tr><td>内容详实、体会中肯、思路清晰、非常切合实际的很优秀</td></tr><tr><td>项目难度很高，或项目完成质量优异，或涉及国家重大信息系统工程且作者本人参加并发挥重要作用</td></tr></tbody></table><p><strong>不及格情况：</strong></p><table tabindex="0"><thead><tr><th>情况</th></tr></thead><tbody><tr><td>虚构情节、论文中有较严重的不真实或不可信的内容出现</td></tr><tr><td>没有项目开发的实际经验，通篇都是浅层次、纯理论的叙述</td></tr><tr><td>所讨论的内容与方法过于陈旧，或者项目的水准非常低下</td></tr><tr><td>内容不切题意，或内容相对很空洞，基本上是泛泛而谈且没有体现深入体会</td></tr><tr><td>正文与摘要的篇幅过于短小</td></tr><tr><td>文理很不通顺、错别字很多、条理与思路不清晰、字迹过于潦草等情况相对严重</td></tr></tbody></table><hr><h3 id="四、论文框架-★" tabindex="-1">四、论文框架 ★ <a class="header-anchor" href="#四、论文框架-★" aria-label="Permalink to &quot;四、论文框架 ★&quot;">​</a></h3><blockquote><p>论文整体结构：摘要 → 项目背景 → 过渡 → 理论部分 → 实践部分 → 结尾</p></blockquote><h4 id="_1-摘要-300-字" tabindex="-1">1. 摘要（~300 字） <a class="header-anchor" href="#_1-摘要-300-字" aria-label="Permalink to &quot;1. 摘要（~300 字）&quot;">​</a></h4><p>摘要由 3 个部分组成：</p><ol><li><strong>项目背景介绍</strong>：项目缘由、时间、名称、建设内容，作者工作角色和内容</li><li><strong>技术简介</strong>：结合题目要求简单介绍采用了什么技术/方法/措施，解决了什么问题</li><li><strong>项目效果简述</strong>：语言要精炼、概括，不宜详细展开，不建议分段</li></ol><h4 id="_2-项目背景-400-500-字-★" tabindex="-1">2. 项目背景（~400~500 字）★ <a class="header-anchor" href="#_2-项目背景-400-500-字-★" aria-label="Permalink to &quot;2. 项目背景（~400~500 字）★&quot;">​</a></h4><p>采用 <strong>5W2H</strong> 模式展开：</p><table tabindex="0"><thead><tr><th>要素</th><th>说明</th></tr></thead><tbody><tr><td><strong>Why</strong></td><td>项目的由来、缘起、项目定位、项目目标</td></tr><tr><td><strong>When</strong></td><td>何时，建议选近三年的项目，工期建议半年至一年</td></tr><tr><td><strong>Where</strong></td><td>何地，介绍项目发生地，不能出现实际城市名（建议：某省/某市）</td></tr><tr><td><strong>Who</strong></td><td>甲乙双方，甲方名称需脱敏处理，乙方称&quot;我司/我单位/我厂/我公司&quot;</td></tr><tr><td><strong>What</strong></td><td>项目名称、建设内容、作者的工作内容</td></tr><tr><td><strong>How much</strong></td><td>项目规模、项目预算</td></tr><tr><td><strong>How</strong></td><td>采用的技术、框架、方法、工具、措施</td></tr></tbody></table><blockquote><p>项目选择优先级：首选自己参与过、有体会的项目 → 其次选未参与但熟悉的项目 → 最后选通过阅读文档能理解的项目</p></blockquote><h4 id="_3-过渡部分-100-字" tabindex="-1">3. 过渡部分（~100 字） <a class="header-anchor" href="#_3-过渡部分-100-字" aria-label="Permalink to &quot;3. 过渡部分（~100 字）&quot;">​</a></h4><p>起承上启下作用，识别项目关键需求、特征、约束等主客观因素，提出需要采取哪些理论/技术/措施，引出下文。</p><h4 id="_4-理论部分-400-600-字-★" tabindex="-1">4. 理论部分（~400~600 字）★ <a class="header-anchor" href="#_4-理论部分-400-600-字-★" aria-label="Permalink to &quot;4. 理论部分（~400~600 字）★&quot;">​</a></h4><ul><li>针对论文题干第二小问的要求，单独完整地逐一应答</li><li>又称分论点，要紧扣题干，问什么答什么</li><li>着重论述分论点的基本概念、基本原理、应用场景，适当简单举例</li><li>可以用自己的语言理解阐述，但要严谨、科学、正确</li><li>注意控制字数，切忌洋洋洒洒上千字</li></ul><h4 id="_5-实践部分-1000-1200-字-★" tabindex="-1">5. 实践部分（~1000~1200 字）★ <a class="header-anchor" href="#_5-实践部分-1000-1200-字-★" aria-label="Permalink to &quot;5. 实践部分（~1000~1200 字）★&quot;">​</a></h4><blockquote><p>论文最重要的部分，最能体现作者水平的高低。</p></blockquote><ul><li>结构上与理论部分前后呼应，紧扣分论点</li><li>建议提炼小标题（要能统领全段内容）</li><li>每个分论点采用 <strong>&quot;Why + How&quot;</strong> 来阐述：先分析问题，然后解决问题</li><li>深入浅出，切忌纸上谈兵、干巴巴的理论堆砌</li><li>注意扬长避短，不能把实践部分写成产品介绍</li></ul><h4 id="_6-结尾-300-400-字" tabindex="-1">6. 结尾（~300~400 字） <a class="header-anchor" href="#_6-结尾-300-400-字" aria-label="Permalink to &quot;6. 结尾（~300~400 字）&quot;">​</a></h4><ul><li>首先呼应论点</li><li>可介绍项目出现的小问题、项目效果、下一步计划、作者的收获等</li><li>首尾呼应，避免前后矛盾</li><li>阐述问题简单带过即可，切忌滔滔不绝</li></ul><hr><h3 id="五、备考建议" tabindex="-1">五、备考建议 <a class="header-anchor" href="#五、备考建议" aria-label="Permalink to &quot;五、备考建议&quot;">​</a></h3><ul><li>若时间允许，把近三年的历年真题都写一遍</li><li>论文考试范围：系统建模、软件架构设计、系统分析与设计、系统可靠性分析与设计、系统安全性和保密性设计</li><li>字数参考：摘要 290~320 + 正文 2200~2800 ≈ 总计 2500~3120 字</li><li>论文字数约 300+2200 ≈ 约 2500 字</li></ul><h3 id="六、字数参考汇总" tabindex="-1">六、字数参考汇总 <a class="header-anchor" href="#六、字数参考汇总" aria-label="Permalink to &quot;六、字数参考汇总&quot;">​</a></h3><table tabindex="0"><thead><tr><th>结构部分</th><th style="text-align:center;">建议字数</th></tr></thead><tbody><tr><td>摘要</td><td style="text-align:center;">290~320</td></tr><tr><td>项目背景</td><td style="text-align:center;">400~500</td></tr><tr><td>过渡部分</td><td style="text-align:center;">~100</td></tr><tr><td>理论部分</td><td style="text-align:center;">400~600</td></tr><tr><td>实践部分</td><td style="text-align:center;">1000~1200</td></tr><tr><td>结尾</td><td style="text-align:center;">300~400</td></tr><tr><td><strong>合计</strong></td><td style="text-align:center;"><strong>~2490~3120</strong></td></tr></tbody></table>',46)])])}const u=r(l,[["render",o]]);export{c as __pageData,u as default};
